client_script:
frappe.web_form.after_load = function() {
  var doc = frappe.web_form.doc;
  if (doc && doc.name) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#e8f5ed;color:#006837;border-left:4px solid #00A651;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">R\u00e9f. PV-ENT : ' + doc.name + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
  var roles = (frappe.boot && frappe.boot.user && frappe.boot.user.roles) ? frappe.boot.user.roles : [];
  var state = (doc && (doc.workflow_state || doc.statut)) || 'Brouillon';
  var rules = {
    'signature_livreur': { states: ['Brouillon'], roles: [] },
    'livreur_nom': { states: ['Brouillon'], roles: [] },
    'signature_magasin': { states: ['En attente Magasin'], roles: ['Stock Manager','Stock User','Charg\u00e9 des Stocks','System Manager'] },
    'signature_comptable': { states: ['En attente Comptable'], roles: ['Responsable Comptable','Accounts Manager','Accounts User','System Manager'] },
    'signature_audit': { states: ['En attente Audit'], roles: ['Auditeur Interne','System Manager'] }
  };
  ['signature_livreur','signature_magasin','signature_comptable','signature_audit'].forEach(function(f){ try{ frappe.web_form.set_df_property(f,'read_only',1); }catch(e){} });
  Object.keys(rules).forEach(function(field) {
    var rule = rules[field];
    var stateOk = rule.states.indexOf(state) !== -1;
    var roleOk = rule.roles.length === 0 || rule.roles.some(function(r){ return roles.indexOf(r) !== -1; });
    if (stateOk && roleOk) { try{ frappe.web_form.set_df_property(field,'read_only',0); }catch(e){} }
  });
  if (doc && doc.statut) {
    var cm = {'Approuv\u00e9':'#2e7d32','Rejet\u00e9':'#c62828','Brouillon':'#757575','En attente Magasin':'#e65100','En attente Comptable':'#1565c0','En attente Audit':'#6a1b9a'};
    var c = cm[doc.statut] || '#e65100';
    var el = document.createElement('div');
    el.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:'+c+';color:#fff;border-radius:6px;display:inline-block;font-weight:700;">\u00c9tat\u00a0: '+doc.statut+'</div>';
    var w2 = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w2) w2.prepend(el);
  }
};
frappe.web_form.on('load', function(){
  var doc = frappe.web_form.doc;
  if (!doc.livreur_nom && frappe.session && frappe.session.user) {
    frappe.call({ method:'frappe.client.get_value', args:{ doctype:'Employee', filters:{ user_id: frappe.session.user }, fieldname:'employee_name' }, callback:function(r){ if(r.message && r.message.employee_name) frappe.web_form.set_value('livreur_nom', r.message.employee_name); } });
  }
});
frappe.web_form.on('fournisseur_libre', function(field, value){
  if (!value || frappe.web_form.doc.fournisseur) return;
  if (window.__kya_fournisseur_prompt) return;
  window.__kya_fournisseur_prompt = true;
  frappe.confirm('Le fournisseur "' + value + '" n\'existe pas encore.\n\nL\'enregistrer maintenant dans la base fournisseurs ?', function(){
    window.open('/app/supplier/new?supplier_name=' + encodeURIComponent(value), '_blank');
  });
});
